def so_du_cuoi(giao_dich):
    so_du = {}
    for tk, loai, tien in giao_dich:
        hien = so_du.get(tk, 0)
        if loai == "nap":
            hien += tien
        elif loai == "rut" and tien <= hien:
            hien -= tien
        so_du[tk] = hien
    return so_du
